import { api, tags, urlUtils } from '@igblsln/store';
const API_PATH = '/estimate/labour/';
export const labourApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listLabours: build.query({
            query: ({ category }) => {
                const params = new URLSearchParams();
                if (category)
                    params.append('category', category.toString());
                return {
                    url: urlUtils(API_PATH, `?${params.toString()}`),
                };
            },
            providesTags: (result) => result ? [
                ...result === null || result === void 0 ? void 0 : result.results.map(({ key }) => ({ type: tags.LABOUR, key })),
                { type: tags.LABOUR, id: 'LIST' },
            ] : [{ type: tags.LABOUR, id: 'LIST' }],
        }),
        getLabour: build.query({
            query: (id) => `${API_PATH}${id}`,
            providesTags: (result, error, id) => [{ type: tags.LABOUR, id }],
        }),
        addLabour: build.mutation({
            query: (body) => ({
                url: API_PATH,
                method: 'POST',
                body,
            }),
            invalidatesTags: [{ type: tags.LABOUR, id: 'LIST' }],
        }),
        updateLabour: build.mutation({
            query: ({ key, data }) => ({
                url: `${API_PATH}${key}`,
                method: 'PUT',
                body: data,
            }),
            invalidatesTags: (result, error, { key }) => [
                { type: tags.LABOUR, id: key },
                { type: tags.LABOUR, id: 'LIST' }
            ],
        }),
        deleteLabour: build.mutation({
            query: (id) => ({
                url: `${API_PATH}${id}`,
                method: 'DELETE',
            }),
            invalidatesTags: [{ type: tags.LABOUR, id: 'LIST' }],
        }),
    })
});
export const { useListLaboursQuery, useGetLabourQuery, useAddLabourMutation, useUpdateLabourMutation, useDeleteLabourMutation, } = labourApi;
