import { api, tags, urlUtils } from '@igblsln/store';
const API_PATH = '/estimate/workinstance_and_schedule';
export const workScheduleInstanceApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listWorkInstanceAndSchedule: build.query({
            query: ({ project, block, category }) => {
                const params = new URLSearchParams();
                if (project)
                    params.append('project', project.toString());
                if (block)
                    params.append('block', block.toString());
                if (category)
                    params.append('category', category.toString());
                params.append('without_pagination', '1');
                const queryString = params.toString();
                return {
                    url: urlUtils(API_PATH, queryString ? `?${queryString}` : ''),
                };
            },
            transformResponse: (response) => (response === null || response === void 0 ? void 0 : response.results) || response,
            providesTags: [{ type: tags.WORK_SCHEDULE_INSTANCE, id: 'LIST' }],
        }),
        createWorkInstanceAndSchedule: build.mutation({
            query: (body) => ({
                url: API_PATH,
                method: 'POST',
                body,
            }),
            invalidatesTags: [{ type: tags.WORK_SCHEDULE_INSTANCE, id: 'LIST' }],
        }),
        updateWorkInstanceAndSchedule: build.mutation({
            query: ({ id, body }) => ({
                url: urlUtils(`${API_PATH}/${id}`),
                method: 'PUT',
                body,
            }),
            invalidatesTags: [{ type: tags.WORK_SCHEDULE_INSTANCE, id: 'LIST' }],
        }),
    }),
});
export const { useListWorkInstanceAndScheduleQuery, useCreateWorkInstanceAndScheduleMutation, useUpdateWorkInstanceAndScheduleMutation, } = workScheduleInstanceApi;
